import{z as p,x as A,o as n,c as B,q as l,j as r,D as e,d as o,s as i,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"提示压缩 LLMLingua","description":"","frontmatter":{"title":"提示压缩 LLMLingua","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/prompt-compression.md","filePath":"llm/prompt-compression.md","lastUpdated":1791063341000}'),m={name:"llm/prompt-compression.md"};function L(d,a,u,P,h,g){const E=A("Mermaid");return n(),B("div",null,[a[2]||(a[2]=l('<h1 id="提示压缩-llmlingua" tabindex="-1">提示压缩 LLMLingua <a class="header-anchor" href="#提示压缩-llmlingua" aria-label="Permalink to &quot;提示压缩 LLMLingua&quot;">​</a></h1><div class="epigraph"><p>系统提示、检索段落、对话历史里，大量 token 对下一句几乎没有信息。先用小模型打掉它们，大模型按预算看见更短的前缀。</p><footer>—— Jiang et al., LLMLingua, EMNLP 2023；长上下文检索见 LongLLMLingua</footer></div><p><a href="/llm/tensor-decomposition">上一课</a> 压的是权重。本课权重冻结：压的是<strong>提示</strong>。缺口是上下文窗口与 prefill FLOPs 随 token 线性（注意力还更差），RAG 与工具轨迹把前缀撑满。LLMLingua 用小 LM 的困惑度做逐 token 预算控制，迭代删掉「可预测因而信息少」的词。后课词表裁剪回到模型文件内部。不重写 <a href="/llm/prompt-cache">Prompt Cache</a> 的前缀缓存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户真正的问句往往只有几十 token，前面却挂着几千 token 的说明与文档。完整前缀质量最好，贵。截断尾部或头部会误删关键约束。需要按<strong>信息量</strong>分配预算：不可预测、任务相关的 token 留下，套话与重复检索句删掉。小模型的 PPL 是便宜代理；它与大模型的信息量不完全一致，这是误差来源。</p><p>这不是 KV 量化，也不是 Deja Vu 跳通道。输出词表与权重原封不动。压缩器失败的可见症状是丢约束、丢引用、丢格式，而不是 PPL 微涨。</p><p><span class="marginnote">LongLLMLingua 把问题改成：在多文档里先选段再压 token，避免平均地从每篇各删一半。RAG 场景应走这条，而不是对拼接后的超长串做一次全局删词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算控制器：给定目标压缩比，用小模型对提示分段算条件 PPL，迭代去掉当前最可预测的 token，直到长度达标。保留特殊标记、数字、代码标识符的白名单。与大模型的 chat template 对齐，否则压缩器看见的切分与主模型不同，分数无意义——接到 <a href="/llm/pretokenization-regex">预分词正则</a> 的同一快照纪律。</p><p><span class="marginnote">数字实例：把 4000 token 的 RAG 前缀压到 2000（压缩比 2×），prefill 的算力与费用大致省一半，首 token 也明显提前。但省钱的前提是下游任务分数不掉——若准确率从 82% 掉到 70%，省下的一半预算通常远不够重试与纠错的代价。</span></p><p>评测必须用下游：问答准确、引用是否仍在、格式是否可解析。禁止只报「压缩比 × 速度」而不报任务分。与缓存：压缩后的前缀哈希变了，Prompt Cache 命中率下降，是另一笔账。</p>',11)),(n(),r(s,null,{default:e(()=>[i(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%95%BF%E6%8F%90%E7%A4%BA%22%5D%20--%3E%20S%5B%22%E5%B0%8F%E6%A8%A1%E5%9E%8B%E9%80%90%E6%AE%B5%20PPL%22%5D%0A%20%20S%20--%3E%20B%5B%22%E9%A2%84%E7%AE%97%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%9F%AD%E6%8F%90%E7%A4%BA%22%5D%0A%20%20C%20--%3E%20LLM%5B%22%E4%B8%BB%E6%A8%A1%E5%9E%8B%20prefill%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"可预测 token 对交叉熵贡献小，删掉后大模型的条件分布往往仍能补全语法。任务关键实体恰好是高 PPL 的那类，所以代理与目标大体同向。失败在：小模型与大模型的分词器或领域不一致，于是「可预测」指错对象；以及对话里的指代，删了先行词后短提示在主模型里无法还原。",-1)),a[5]||(a[5]=t("p",null,"删与留的边界可以画成一次逐 token 的分流：",-1)),(n(),r(s,null,{default:e(()=>[i(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%B0%8F%E6%A8%A1%E5%9E%8B%E6%89%AB%E6%AF%8F%E4%B8%AA%20token%22%5D%20--%3E%20Q%7B%22%E8%AF%A5%20token%20%E5%B1%9E%E4%BA%8E%E5%93%AA%E7%B1%BB%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%A5%97%E8%AF%9D%C2%B7%E5%8F%AF%E9%A2%84%E6%B5%8B%20%E4%BD%8EPPL%22%7C%20D%5B%22%E5%88%A0%22%5D%0A%20%20Q%20--%3E%7C%22%E5%AE%9E%E4%BD%93%C2%B7%E6%95%B0%E5%AD%97%C2%B7%E7%BA%A6%E6%9D%9F%20%E9%AB%98PPL%22%7C%20K%5B%22%E7%95%99%22%5D%0A%20%20Q%20--%3E%7C%22%E8%A2%AB%E6%8C%87%E4%BB%A3%E7%9A%84%E5%85%88%E8%A1%8C%E8%AF%8D%22%7C%20K%0A%20%20Q%20--%3E%7C%22%E4%BB%A3%E7%A0%81%C2%B7schema%C2%B7%E6%8E%A8%E7%90%86%E9%93%BE%22%7C%20W%5B%22%E6%95%B4%E6%AE%B5%E7%99%BD%E5%90%8D%E5%8D%95%22%5D%0A%20%20D%20--%3E%20O%5B%22%E9%A2%84%E7%AE%97%E8%BE%BE%E6%A0%87%E5%90%8E%E9%80%81%E4%B8%BB%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20K%20--%3E%20O%0A%20%20W%20--%3E%20O%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">困惑度（PPL）可以翻译成「模型读到下一个词时有多惊讶」：「综上所述」「如前所述」这类套话几乎不用猜，惊讶度为零，删掉也补得回来；而「赔偿上限 40 天」里的数字让人无从预测，惊讶度最高，删了任务就崩。压缩器本质上是在按惊讶度分配生存权。</span></p><p>与 RL 推理链：压缩思维链会把自检步骤删成套话，<a href="/llm/grpo">GRPO</a> 训出的长链不要当普通系统提示压。用户可见问句通常不压。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要对已经短的提示再压。不要把压缩器本身做成又一次大模型调用还宣称省钱。法律、代码、JSON schema 应白名单整段保留。下一课词表裁剪：减的是 embedding 行数，提示仍可以很长。</p><p><span class="marginnote">常见误区：初学者容易以为「删掉的只是不重要的连接词」。实际上最阴险的失败是被删的是指代的先行词——「甲方应在签约后付款」被压掉「甲方」，后面的「它逾期」就悬空了，主模型只能猜。所以评测要盯约束与引用是否存活，而不是平均困惑度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LLMLingua 压输入 token，不改 \\(W\\)；代理是小模型 PPL。</li><li>验收用下游约束是否还在，不用压缩比本身。</li><li>RAG 先选段再压词；分词器必须与主模型一致。</li><li>推理长链与 schema 不要当套话删。</li><li>出处：Jiang et al., EMNLP 2023 LLMLingua；后续 LongLLMLingua。</li></ul>',7))])}const f=p(m,[["render",L]]);export{D as __pageData,f as default};
